        // metoda pro doplnění DTo ISp pro zobrazení
        napln_isp (data_isp : Gordic.Ada.Interface.GISPAkceDto) {
            var that = this;

            //data_isp.ixs = "";
            //data_isp.ixs = data_isp.ixs + data_isp.rok;
            //data_isp.ixs = data_isp.ixs + data_isp.cislo;
            data_isp.ixs = data_isp.ixs_csl;
            data_isp.ixs_prr = that.filter_akce.ixs_prr;

            data_isp.dat_inp_txt = "";
            if (data_isp.dat_inp != null) {
                data_isp.dat_inp_txt = '(' + Gordic.Templates.Formatters.datetime(data_isp.dat_inp, "dd.MM.yyyy") + ')';
            }

            if (data_isp.popis_ixb == null) data_isp.popis_ixb = '';
            data_isp.popis_ixb = (data_isp.popis_ixb == '' ? '' : data_isp.popis_ixb);
            data_isp.popis_ixb_label = (data_isp.popis_ixb == '' ? 'Bez přílohy' : 'Příloha: ');
            data_isp.stav1 = (data_isp.s_inp == 0 ? 'fa-thumbs-down' : (data_isp.s_inp == 1 ? 'fa-thumbs-up' : 'fa-thumbs-o-up'));
            data_isp.stav1_color = (data_isp.s_inp == 0 ? 'Salmon' : (data_isp.s_inp == 1 ? 'LightBlue' : 'Teal'));          
            data_isp.dat_inp_zobr = (data_isp.s_inp != 1 ? '' : (data_isp.dat_inp_txt));

            data_isp.aktivita_txt = (data_isp.aktivita == 600 ? "Ke schválení" : (data_isp.aktivita == 300 ? "Návrh" : (data_isp.aktivita == 100 ? "Schváleno" : "Zamítnuto")));

            //fa-exclamation-triangle g-state-text g-state-warning
            $.extend(true, data_isp, { title: { icon: data_isp.stav1, text: data_isp.srvstip_nazev } });
            $.extend(true, data_isp, { date: { text: data_isp.schv_spec_txt, value: data_isp.dat_inp_txt, meaning: ((data_isp.priz_pov == 1) && (data_isp.s_inp != 1)) ? 'error' : 'success' } });
            $.extend(true, data_isp, { user: { value: data_isp.nazev_ref, description: data_isp.nazev_fun, dat_zmena: Gordic.Templates.Formatters.datetime(data_isp.dat_zmena) } });
            $.extend(true, data_isp, { state: { value: data_isp.aktivita_txt, meaning: (data_isp.aktivita == 100 ? 'positive' : data_isp.aktivita == 500 ? 'error' : data_isp.aktivita == 600 ? 'info' : 'warning') } });

            if (data_isp.popis_ixb != '') {
                $.extend(true, data_isp, {
                    attachments: new GAction({
                        name: "actAttachments",
                        icon: "gi-attachment",
                        caption: data_isp.popis_ixb,
                        tooltip: data_isp.popis_ixb.length <= 20 ? data_isp.popis_ixb : "Příloha",
                        run: (ev, ctx) => {
                            if ((data_isp.Permissions?.JsemVlastnik.value == true) || (that.globals.Param_Zobr_El_Pri_Nevlastnik == Interface.TypProvedeniOperaceEnum.Ano)) {
                                var gc = new GContent("Gordic.Ada.WebClient.GAkceISPSeznam"); //dotažení řádku ze serveru
                                gc.call<Gordic.Gin.Interface.GFileInStringDto>("GetFileZUloziste", { Ixb: ctx.item.data.ixb })
                                    .done(function (r) {
                                        if (r) {
                                            GBrowserExtras.documentSaveOpenLocal(r.Name!, r.Bytes!)
                                                .done(function (retVal) { })
                                                .fail(function (err) { Gordic.Gui.WebApp.Utils.showReasonFlash(gc, err); })
                                                .always(function () {
                                                    gc.endOperation();
                                                });

                                        }
                                    })
                            }
                            else {
                                // that.showFlash({ label: that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Nemáte práva pro zobrazení příloh PP, kde nejste zpracovatelem" : "Nemáte práva pro zobrazení příloh akce, kde nejste zpracovatelem", state: "error", timer: 5000, id: "msgFlashISP" });
                                that.dialogs.messageBox("Chyba", that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Nemáte práva pro zobrazení příloh PP, kde nejste zpracovatelem" : "Nemáte práva pro zobrazení příloh akce, kde nejste zpracovatelem", [GDlg.mbbCancel], GDlg.mbiError)
                            }
                            //OpenElSouborZUloziste(ctx, data_isp.ixb);
                        }
                    })
                });
            } else {
                if (data_isp.priz_pov_ixb == 1) {
                    $.extend(true, data_isp, {
                        attachments: new GAction({
                            name: "actAttachments",
                            icon: "gi-attachment",
                            enabled: true,
                            customClass: "g-state-error g-state-text",
                            caption: "bez příloh",
                            run: (ev, ctx) => {
                            }
                        })
                    });
                }
                else {
                    $.extend(true, data_isp, {
                        attachments: new GAction({
                            name: "actAttachments",
                            icon: "gi-attachment",
                            enabled: true,
                            customClass: "g-state-success g-state-text",
                            caption: "bez příloh",
                            run: (ev, ctx) => {
                            }
                        })
                    });
                }
            }

            return data_isp
        }

