        kontrola_pro_dat_splneni( l_form : any, pole_stav : any, pole_aktivita: any ) {
            if ((pole_stav != null) && (pole_aktivita != null)) {
                if ((pole_stav.schv_spec != null) && (pole_aktivita.aktivita != null)) {
                    if ((pole_aktivita.aktivita == 100) || (pole_aktivita.aktivita == 600))  {
                        l_form.findFields("dat_inp").gfield("disable");
                        l_form.findFields("schv_spec").gfield("disable");
                        l_form.findFields("ixb").gfield("disable");
                        l_form.findFields("ixp_spis").gfield("disable");
                        l_form.findFields("ixp_dokument").gfield("disable");
                    }
                }
            }
        }

